 "content": "def transform(grid):
    """Overlay two panels: matching cells are 3, other cells use background.

    A uniform divider may be vertical or horizontal, separating equal-sized
    panels. The background is the color common to the panels but absent from
    the sparse clue colors in the first panel.
    """
    h, w = len(grid), len(grid[0])
    candidates = []
    for c in range(1, w - 1):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            if c == w - c - 1:
                candidates.append(("v", c))
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            candidates.append(("h", r))
    if len(candidates) != 1:
        raise ValueError("expected a centered uniform divider")
    orient, sep = candidates[0]
    if orient == "v":
        a = [row[:sep] for row in grid]
        b = [row[sep + 1:] for row in grid]
    else:
        a = grid[:sep]
        b = grid[sep + 1:]
    if any(len(a[r]) != len(b[r]) for r in range(len(a))):
        raise ValueError("unequal panels")
    colors_a = {x for row in a for x in row}
    colors_b = {x for row in b for x in row}
    common = colors_a & colors_b
    # Unique shared color is the usual background. If one panel contains a
    # sparse marker color and the other its background, select the latter.
    if len(common) == 1:
        background = next(iter(common))
    else:
        counts_a = {}
        for row in a:
            for x in row:
                counts_a[x] = counts_a.get(x, 0) + 1
        background = max(common, key=lambda x: counts_a.get(x, 0))
